sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
uniform float amount;
uniform float threshold;
uniform float showMask;
half3 tap(float2 p)
{
    half4 s = image.eval(p);
    return s.rgb / max(s.a, 0.001);
}
half softGate(half d, half t)
{
    if (t <= 0.0) return 1.0;
    return smoothstep(t, t + max(t * 0.5, half(0.001)), abs(d));
}
half4 main(float2 coord)
{
    half4 c = image.eval(coord);
    if (c.a <= 0.001) return half4(0.0);
    half3 col = c.rgb / c.a;
    float r = strength * 4.0;
    half3 blurred = (tap(coord + float2(-r, -r)) + 2.0 * tap(coord + float2(0.0, -r)) + tap(coord + float2(r, -r)) + 2.0 * tap(coord + float2(-r, 0.0)) + 4.0 * col + 2.0 * tap(coord + float2(r, 0.0)) + tap(coord + float2(-r, r)) + 2.0 * tap(coord + float2(0.0, r)) + tap(coord + float2(r, r))) / 16.0;
    half3 diff = col - blurred;
    half t = half(max(threshold, 0.0) * 0.25);
    half3 g = half3(softGate(diff.r, t), softGate(diff.g, t), softGate(diff.b, t));
    half amt = half(amount);
    half3 corrected = clamp(col + amt * diff * g, half3(0.0), half3(1.0));
    half3 ad = abs(diff);
    half m = clamp((ad.r + ad.g + ad.b) * half(1.3333333), 0.0, 1.0);
    if (showMask > 0.5) return half4(half3(m) * c.a, c.a);
    return half4(corrected * c.a, c.a);
}
